+        child: Some(child),
+        mapped_attempt: Some(MappedSshUdsAttemptV1 {
+            socket_path,
+            socket_device: 0,
+            socket_inode: 0,
+            known_hosts_path,
+            known_hosts_existed,
+            known_hosts_before,
+        }),
+    };
+    if let Some(mut child) = failed.child.take() {
+        let _ = child.kill();
+        let _ = child.wait();
+    }
