        fail()
    if not re.fullmatch(r"[0-9a-f]{32}", machine_id):
        fail()
    if not re.fullmatch(r"0|[1-9][0-9]*", uid):
        fail()
    if not valid_text(vm_name) or not valid_text(account):
        fail()
