    pat=rf'(?ms)^    #\[test\]\n    fn {name}\(\).*?(?=^    #\[test\]|^\}})'
    repl='    #[test]\n'+body.strip()+'\n\n'
    s2,n=re.subn(pat,repl,s,count=1)
    if n!=1: raise SystemExit(f'{path}:{name}:{n}')
    p.write_text(s2)

