//! Forwarding management for host-VM communication.

use crate::transport::{
    compatibility_tcp_endpoint, managed_host_socket_path, CANONICAL_GUEST_SOCKET_PATH,
    CANONICAL_GUEST_SOCKET_URI, COMPATIBILITY_TCP_HOST, COMPATIBILITY_TCP_PORT,
