/// Open the fixed local XPC publisher channel through the installed, designated executor.
///
/// The client never accepts a caller-supplied executable, service name, or transport fallback. The
/// executor owns the actual XPC connection and returns one JSON response on its fixed stdio relay.
pub fn open_mac_xpc_channel_v1(operation: &str, request: &[u8]) -> Result<Vec<u8>> {
    if !cfg!(target_os = "macos") || !Path::new(MAC_EXECUTOR_V1).is_file() {
        return Err(provider_unavailable_error(
            "macos",
            "open_mac_xpc_channel_v1",
        ));
    }
    let mut child = Command::new(MAC_EXECUTOR_V1)
        .arg(operation)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .context("spawn fixed macOS lifecycle executor")?;
    child
        .stdin
        .as_mut()
        .ok_or_else(|| anyhow::anyhow!("macOS lifecycle executor stdin is unavailable"))?
        .write_all(request)
        .context("write macOS lifecycle publisher request")?;
    drop(child.stdin.take());
    let mut response = Vec::new();
    child
        .stdout
        .as_mut()
        .ok_or_else(|| anyhow::anyhow!("macOS lifecycle executor stdout is unavailable"))?
        .read_to_end(&mut response)
        .context("read macOS lifecycle publisher response")?;
    let output = child
        .wait_with_output()
        .context("wait for fixed macOS lifecycle executor")?;
    if !output.status.success() {
        bail!(
            "macOS lifecycle executor failed: {}",
            String::from_utf8_lossy(&output.stderr).trim()
        );
    }
    if response.is_empty() {
        bail!("macOS lifecycle executor returned an empty XPC relay response");
    }
    Ok(response)
}

/// Verify the fixed publisher service and caller PID carried by its executor-bound response.
pub fn attest_mac_publisher_response_v1(response: &[u8]) -> Result<()> {
    let value: Value =
        serde_json::from_slice(response).context("decode macOS publisher attestation")?;
    let attestation = value
        .get("xpc_attestation")
        .and_then(Value::as_object)
        .ok_or_else(|| anyhow::anyhow!("macOS publisher response is missing xpc_attestation"))?;
    let service = attestation
        .get("mach_service")
        .and_then(Value::as_str)
        .ok_or_else(|| anyhow::anyhow!("macOS publisher response is missing mach_service"))?;
    if service != MAC_MACH_SERVICE_V1 {
        bail!("macOS publisher response names an unexpected Mach service");
    }
    let caller_pid = attestation
        .get("caller_pid")
        .and_then(Value::as_u64)
        .ok_or_else(|| anyhow::anyhow!("macOS publisher response is missing caller_pid"))?;
    if caller_pid != u64::from(std::process::id()) {
        bail!("macOS publisher response caller_pid does not match this client");
    }
