fn run_linux_executor_frame_with_paths_v1(
    sudo_path: &Path,
    env_path: &Path,
    executor_path: &Path,
    args: &[&str],
    request_bytes: &[u8],
) -> Result<Vec<u8>> {
    let (parent_socket, child_fd) = open_linux_seqpacket_channel_v1()?;

    let mut command = Command::new(sudo_path);
